import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CHeM0PsO.js";const n="/images/agent-checkin.webp",s="/images/agent-usage.webp",_=JSON.parse('{"title":"用量与额度","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/usage.md","filePath":"guide/agent/usage.md","lastUpdated":1793029602000}'),i={name:"guide/agent/usage.md"};function l(g,t,d,h,c,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="用量与额度" tabindex="-1">用量与额度 <a class="header-anchor" href="#用量与额度" aria-label="Permalink to &quot;用量与额度&quot;">​</a></h1><p>智能体的对话、生图、识图、便签压缩都消耗<strong>额度</strong>。智能体页顶部的「我的用量」「模型」「签到」三个标签页与额度相关。</p><h2 id="额度从哪来" tabindex="-1">额度从哪来 <a class="header-anchor" href="#额度从哪来" aria-label="Permalink to &quot;额度从哪来&quot;">​</a></h2><ul><li><strong>签到</strong>：每天在「签到」页领取额度。奖励由当日手气与连续签到倍率共同决定，特定身份组有额外倍率，节日可能有活动加成。最近 7 天内漏签的日期可以补签，补签消耗额度并占用每月补签次数。</li><li><strong>卡密兑换</strong>：在「我的用量」页输入卡密兑换。</li><li><strong>管理员签发</strong>：活动奖励等由管理员直接发放。</li></ul><p><img src="'+n+'" alt="签到"></p><h2 id="费用怎么算" tabindex="-1">费用怎么算 <a class="header-anchor" href="#费用怎么算" aria-label="Permalink to &quot;费用怎么算&quot;">​</a></h2><ul><li><strong>对话</strong>：按模型卡片标注的单次费用计费，切换模型即切换单价。部分模型标注「免费」或带有每日免费次数。</li><li><strong>生图</strong>：按所选生图模型的「每张费用」计费。</li><li><strong>识图</strong>：发送图片触发识图时按次计费。</li><li><strong>便签压缩</strong>：为会话单独选择压缩模型时，摘要按该模型单独计费，与主回复分开扣（时机可能略有先后）。</li></ul><p>发送前，会话的「模型」标签页会显示<strong>预计单次发送费用</strong>。失败的请求<strong>不计费</strong>。</p><h2 id="我的用量" tabindex="-1">我的用量 <a class="header-anchor" href="#我的用量" aria-label="Permalink to &quot;我的用量&quot;">​</a></h2><p>「我的用量」页显示余额、总请求数、成功率和费用，并提供：</p><ul><li><strong>卡密兑换</strong>入口。</li><li><strong>用量图表</strong>（近 30 天）：请求量、扣减额度、Token 用量趋势与用途构成。</li><li><strong>模型用量分析</strong>、<strong>角色使用</strong>、<strong>风格使用</strong>（近 30 天）。</li><li><strong>消费日志</strong>与<strong>最近请求记录</strong>：每次调用的时间、类型、模型、状态、耗时和费用。</li></ul><p><img src="'+s+'" alt="我的用量"></p><h2 id="自定义模型" tabindex="-1">自定义模型 <a class="header-anchor" href="#自定义模型" aria-label="Permalink to &quot;自定义模型&quot;">​</a></h2><p>「模型」页除官方模型外，还可以用自己的 API Key 添加自定义模型（需管理员启用）。自定义模型的调用费用由你的模型供应商收取，不消耗平台额度。</p><h2 id="余额不足" tabindex="-1">余额不足 <a class="header-anchor" href="#余额不足" aria-label="Permalink to &quot;余额不足&quot;">​</a></h2><p>提示「智能体对话余额不足，无法发送」时，可签到、兑换卡密，或切换到免费模型。</p>',16)])])}const m=a(i,[["render",l]]);export{_ as __pageData,m as default};
